"""Canonical API_LOCAL transport for controlled synchronization only."""

from __future__ import annotations

from typing import Any

import requests

from core.server_registry import get_server_by_id, get_server_connection_info
from modules.integrations_runtime.read_only_sql import validate_readonly_sql


class ApiLocalTransportError(RuntimeError):
    def __init__(self, code: str, *, status_code: int | None = None):
        super().__init__(code)
        self.code = code
        self.status_code = status_code


async def resolve_api_local_sync_connection(server_id: str) -> dict[str, Any]:
    normalized_id = str(server_id or "").strip()
    if not normalized_id:
        raise ApiLocalTransportError("SERVER_ID_REQUIRED")

    server = await get_server_by_id(normalized_id, mask_secrets=False)
    if not server:
        raise ApiLocalTransportError("API_LOCAL_CONNECTION_NOT_FOUND")
    if str(server.get("tipo_conexion") or "").strip().upper() != "API_LOCAL":
        raise ApiLocalTransportError("CONNECTION_TYPE_NOT_API_LOCAL")

    connection = await get_server_connection_info(normalized_id)
    if not connection:
        raise ApiLocalTransportError("API_LOCAL_CONNECTION_NOT_FOUND")
    if not str(connection.get("api_url") or "").strip():
        raise ApiLocalTransportError("API_LOCAL_URL_REQUIRED")
    return connection


async def execute_api_local_readonly(
    server_id: str,
    sql: str,
    *,
    timeout_seconds: int = 30,
) -> list[dict[str, Any]]:
    query = validate_readonly_sql(sql)
    if not isinstance(timeout_seconds, int) or not 1 <= timeout_seconds <= 120:
        raise ApiLocalTransportError("INVALID_TIMEOUT")

    connection = await resolve_api_local_sync_connection(server_id)
    headers: dict[str, str] = {}
    credential = connection.get("api_key")
    if credential:
        headers["X-API-Key"] = str(credential)

    try:
        response = requests.get(
            str(connection["api_url"]),
            params={"sql": query},
            headers=headers,
            timeout=timeout_seconds,
        )
    except requests.Timeout as exc:
        raise ApiLocalTransportError("API_LOCAL_TIMEOUT") from exc
    except requests.RequestException as exc:
        raise ApiLocalTransportError("API_LOCAL_UNAVAILABLE") from exc

    if response.status_code != 200:
        raise ApiLocalTransportError(
            "API_LOCAL_HTTP_ERROR",
            status_code=response.status_code,
        )

    try:
        payload = response.json()
    except ValueError as exc:
        raise ApiLocalTransportError("API_LOCAL_INVALID_JSON") from exc

    if isinstance(payload, dict):
        rows = payload.get("data")
    elif isinstance(payload, list):
        rows = payload
    else:
        raise ApiLocalTransportError("API_LOCAL_INVALID_RESPONSE")

    if not isinstance(rows, list) or any(not isinstance(row, dict) for row in rows):
        raise ApiLocalTransportError("API_LOCAL_INVALID_ROWS")
    return rows

from __future__ import annotations

from types import SimpleNamespace

import pytest

from modules.integrations_runtime import api_local_transport as transport


@pytest.mark.asyncio
async def test_rejects_mutation_before_connection_resolution(monkeypatch):
    async def forbidden(*args, **kwargs):
        raise AssertionError("connection must not be resolved")
    monkeypatch.setattr(transport, "get_server_by_id", forbidden)
    with pytest.raises(ValueError, match="ONLY_SELECT_OR_WITH_ALLOWED"):
        await transport.execute_api_local_readonly("server-1", "DELETE FROM dbo.T")


@pytest.mark.asyncio
async def test_rejects_non_api_local_connection(monkeypatch):
    async def fake_server(*args, **kwargs):
        return {"tipo_conexion": "DATA_SOURCE"}
    monkeypatch.setattr(transport, "get_server_by_id", fake_server)
    with pytest.raises(transport.ApiLocalTransportError, match="CONNECTION_TYPE_NOT_API_LOCAL"):
        await transport.resolve_api_local_sync_connection("server-1")


@pytest.mark.asyncio
async def test_executes_select_with_canonical_credentials(monkeypatch):
    async def fake_server(*args, **kwargs):
        return {"tipo_conexion": "API_LOCAL"}
    async def fake_connection(*args, **kwargs):
        return {"api_url": "http://source.invalid/query", "api_key": "opaque"}
    calls = {}
    def fake_get(url, *, params, headers, timeout):
        calls.update(url=url, params=params, headers=headers, timeout=timeout)
        return SimpleNamespace(status_code=200, json=lambda: {"data": [{"SucursalID": "01"}]})
    monkeypatch.setattr(transport, "get_server_by_id", fake_server)
    monkeypatch.setattr(transport, "get_server_connection_info", fake_connection)
    monkeypatch.setattr(transport.requests, "get", fake_get)
    rows = await transport.execute_api_local_readonly(
        "server-1", "SELECT SucursalID FROM Sucursales", timeout_seconds=17
    )
    assert rows == [{"SucursalID": "01"}]
    assert calls["headers"] == {"X-API-Key": "opaque"}
    assert calls["timeout"] == 17


@pytest.mark.asyncio
async def test_invalid_rows_fail_closed(monkeypatch):
    async def fake_server(*args, **kwargs):
        return {"tipo_conexion": "API_LOCAL"}
    async def fake_connection(*args, **kwargs):
        return {"api_url": "http://source.invalid/query", "api_key": None}
    def fake_get(*args, **kwargs):
        return SimpleNamespace(status_code=200, json=lambda: {"data": {"not": "a-list"}})
    monkeypatch.setattr(transport, "get_server_by_id", fake_server)
    monkeypatch.setattr(transport, "get_server_connection_info", fake_connection)
    monkeypatch.setattr(transport.requests, "get", fake_get)
    with pytest.raises(transport.ApiLocalTransportError, match="API_LOCAL_INVALID_ROWS"):
        await transport.execute_api_local_readonly(
            "server-1", "WITH x AS (SELECT 1 AS n) SELECT n FROM x"
        )


@pytest.mark.asyncio
async def test_timeout_is_bounded_before_connection_resolution(monkeypatch):
    async def forbidden(*args, **kwargs):
        raise AssertionError("connection must not be resolved")
    monkeypatch.setattr(transport, "get_server_by_id", forbidden)
    with pytest.raises(transport.ApiLocalTransportError, match="INVALID_TIMEOUT"):
        await transport.execute_api_local_readonly("server-1", "SELECT 1", timeout_seconds=121)
